import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, nowIso, type JobRow } from './db.ts';

const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  try {
    db.prepare(
      'INSERT INTO heartbeat (id, beat_ms) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_ms = excluded.beat_ms',
    ).run(Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}
heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);

// Recovery. Only one worker process runs at a time, so a job still 'running' here was interrupted
// by a previous worker. Undo that interrupted attempt (decrement attempts) so the next claim re-runs
// the same attempt number, keeping attempts within the limit.
db.prepare(
  "UPDATE jobs SET status='queued', attempts=MAX(attempts-1,0), progress_completed=0, run_after=0, updated_at=? WHERE status='running'",
).run(nowIso());

/** Runs one attempt of a claimed-or-claimable queued job. */
async function runAttempt(id: string): Promise<void> {
  const claimed = db
    .prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'")
    .run(nowIso(), id);
  if (Number(claimed.changes) === 0) return;

  const job = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure, before any progress.
    await sleep(STEP_MS);
    if (attempt < MAX_ATTEMPTS) {
      db.prepare("UPDATE jobs SET status='queued', run_after=?, updated_at=? WHERE id=?").run(Date.now() + RETRY_DELAY_MS, nowIso(), id);
    } else {
      db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=?").run(nowIso(), id);
    }
    return;
  }

  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    // Leave the job 'running' on shutdown; recovery picks it up on the next start.
    if (stopping) return;
    db.prepare('UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=?').run(i, nowIso(), id);
  }

  db.prepare("UPDATE jobs SET status='completed', result_output=?, error=NULL, progress_completed=steps, updated_at=? WHERE id=?").run(
    job.input.toUpperCase(),
    nowIso(),
    id,
  );
}

console.log('worker started');
while (!stopping) {
  try {
    const next = db
      .prepare("SELECT id FROM jobs WHERE status='queued' AND run_after<=? ORDER BY seq ASC LIMIT 1")
      .get(Date.now()) as { id: string } | undefined;
    if (!next) {
      await sleep(POLL_MS);
      continue;
    }
    await runAttempt(next.id);
  } catch (e) {
    console.error('worker error:', e);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.close();
console.log('worker stopped');
process.exit(0);

