import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, nowIso, rowToJob, type Job, type JobRow } from './db.ts';

const MAX_BODY_BYTES = 1024 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH_RE = /^\/api\/jobs\/([^/]+)$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

interface FieldError {
  field: string;
  message: string;
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], extraHeaders?: Record<string, string>): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error }, extraHeaders);
}

/** Reads the request body as UTF-8, or returns null when it exceeds the size cap. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function intField(obj: Record<string, unknown>, name: string, min: number, max: number, def: number, fields: FieldError[]): number {
  const v = obj[name];
  if (v === undefined) return def;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
    return def;
  }
  return v;
}

/** Validates the headers and body of a submission. Collects every offending field. */
function parseSubmission(req: IncomingMessage, raw: string | null): { job: NewJob; key: string | undefined } | { fields: FieldError[] } {
  const fields: FieldError[] = [];

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must be 1-128 characters: letters, digits, "_" or "-".' });
  }

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    return { fields };
  }
  if (raw === null) {
    fields.push({ field: 'body', message: `Body must not exceed ${MAX_BODY_BYTES} bytes.` });
    return { fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'Body must be valid JSON.' });
    return { fields };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    return { fields };
  }

  const obj = parsed as Record<string, unknown>;
  for (const name of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'Unknown field.' });
  }

  const input = obj.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'Required.' });
  } else if (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim() === '') {
    fields.push({ field: 'input', message: 'Must be a non-blank string of 1-1000 characters.' });
  }
  const steps = intField(obj, 'steps', 1, 20, 5, fields);
  const failAttempts = intField(obj, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0) return { fields };
  return { job: { input: input as string, steps, failAttempts }, key };
}

type CreateResult = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/** Inserts a job, or resolves an idempotent replay, inside one IMMEDIATE transaction. */
function createJob(newJob: NewJob, key: string | undefined): CreateResult {
  const payload = JSON.stringify({ input: newJob.input, steps: newJob.steps, failAttempts: newJob.failAttempts });
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        return existing.payload === payload ? { kind: 'replayed', job: rowToJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      'INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, created_at, updated_at, run_after, idempotency_key, payload) VALUES (?, ?, ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)',
    ).run(id, 'queued', newJob.input, newJob.steps, newJob.failAttempts, now, now, key ?? null, payload);
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    db.exec('COMMIT');
    return { kind: 'created', job: rowToJob(row) };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

function isHealthy(): 'up' | 'down' {
  const row = db.prepare('SELECT beat_ms FROM heartbeat WHERE id = 1').get() as { beat_ms: number } | undefined;
  return row !== undefined && Date.now() - row.beat_ms < 3000 ? 'up' : 'down';
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  let jobId: string | undefined;
  const match = JOB_PATH_RE.exec(path);
  if (match) {
    try {
      jobId = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'Not found.');
    }
  }

  let allowed: string[] | undefined;
  if (path === '/' || path === '/health' || jobId !== undefined) allowed = ['GET'];
  else if (path === '/api/jobs') allowed = ['GET', 'POST'];
  if (!allowed) return sendError(res, 404, 'not_found', 'Not found.');
  if (!allowed.includes(method)) {
    return sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`, undefined, { allow: allowed.join(', ') });
  }

  if (path === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (path === '/health') {
    return send(res, 200, { status: 'ok', worker: isHealthy() });
  }

  if (jobId !== undefined) {
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(jobId) as unknown as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, rowToJob(row));
  }

  if (method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(rowToJob) });
  }

  // POST /api/jobs
  const raw = await readBody(req);
  const parsed = parseSubmission(req, raw);
  if ('fields' in parsed) {
    return sendError(res, 400, 'invalid_request', 'Invalid request.', parsed.fields);
  }
  const result = createJob(parsed.job, parsed.key);
  if (result.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.kind === 'created' ? 201 : 200, result.job);
}

const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

function shutdown(): void {
  server.close();
  server.closeAllConnections();
  db.close();
  process.exit(0);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

